import semver from "semver";
import { satisfies, maxSatisfying } from "/private/tmp/hb/runsB/pi-2/src/semver.ts";
const pick = <T,>(a: T[]) => a[Math.floor(Math.random() * a.length)];
const id = () => pick(["0","1","2","3","x","X","*","10","01"]);
const pre = () => pick(["","","","-alpha","-beta.1","-beta.2","-1","-0","-rc.1.x","-a.b","-01"]);
const bld = () => pick(["","","","+b","+b.1"]);
const part = () => { const n = pick([1,2,3,3,3]); const ids = [id(),id(),id()].slice(0,n).join("."); return pick(["","","v","="]) + ids + (n===3?pre()+bld():""); };
const cmp = () => pick(["","","^","~","~>",">","<",">=","<=","=","^ ","> "]) + part();
const set = () => Math.random()<0.2 ? `${part()} - ${part()}` : Array.from({length: pick([1,1,2,3])}, cmp).join(pick([" ","  "]));
const range = () => Array.from({length: pick([1,1,2])}, set).join(pick(["||"," || "]));
const ver = () => [pick(["0","1","2","3","10"]),pick(["0","1","2","3"]),pick(["0","1","2","3"])].join(".") + pre() + bld();
let bad = 0;
for (let i = 0; i < 200000; i++) {
  const r = range(); const vs = Array.from({length: 6}, ver);
  for (const v of vs) { let e; try { e = semver.satisfies(v, r); } catch { e = false; } if (e !== satisfies(v, r) && bad++ < 20) console.log("sat", v, JSON.stringify(r), e); }
  let em; try { em = semver.maxSatisfying(vs, r); } catch { em = null; }
  if (em !== maxSatisfying(vs, r) && bad++ < 20) console.log("max", vs, JSON.stringify(r), em);
}
console.log("bad", bad);
EOF
bun fuzz.ts; bun diff.ts | tail -3

